import{_ as o,o as a,c as r,a3 as i}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Perfil favorito no login","description":"","frontmatter":{"title":"Perfil favorito no login","id":"eproc-perfil-favorito-login","plataforma":"eproc","grupo":"Geral do eproc","plano":"free","desde":"1.5.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-perfil-favorito-login"}]]},"headers":[],"relativePath":"funcionalidades/eproc-perfil-favorito-login.md","filePath":"funcionalidades/eproc-perfil-favorito-login.md"}'),s={name:"funcionalidades/eproc-perfil-favorito-login.md"};function l(t,e,n,p,d,c){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="perfil-favorito-no-login" tabindex="-1">Perfil favorito no login <a class="header-anchor" href="#perfil-favorito-no-login" aria-label="Permalink to &quot;Perfil favorito no login&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na tela de escolha de perfil do login, permite marcar um perfil como favorito com uma estrela. Nas próximas entradas, o eploc seleciona esse perfil sozinho, sem depender do perfil padrão do eproc, que costuma se desconfigurar.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de seleção de perfil no login. O favorito também pode ser trocado nas configurações do eploc, no card do recurso (&quot;Escolher perfil favorito&quot;).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Entre no eproc. Na lista de perfis, passe o mouse sobre o perfil desejado.</li><li>Clique na estrela (&quot;Favoritar e entrar&quot;). O perfil vira favorito e você já entra nele.</li><li>Nas próximas vezes, o eploc clica nesse perfil sozinho.</li><li>Para deixar de entrar automaticamente, clique na estrela do perfil favorito na tela de login, ou use <strong>Escolher perfil favorito</strong> nas configurações do eploc.</li></ol><p>Depois de entrar, você troca de perfil pelo seletor do menu superior, como sempre.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar. O favorito é escolhido na tela de login ou em <strong>Escolher perfil favorito</strong>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O favorito é guardado por endereço do eproc e por usuário: 1º e 2º grau, ou usuários diferentes no mesmo navegador, têm favoritos separados.</li><li>Com um favorito definido, a lista de perfis passa direto, sem contagem regressiva. Para usar outro perfil, troque pelo seletor do menu superior depois de entrar.</li></ul>',12)]))}const m=o(s,[["render",l]]);export{u as __pageData,m as default};
